{# Sphinx layout template for the agogo theme. #}
{%- extends "basic/layout.html" %}

{% block header %}
    <div class="header-wrapper" role="banner">
      <div class="header">
        {%- if logo_url %}
          <p class="logo"><a href="{{ pathto(root_doc)|e }}">
            <img class="logo" src="{{ logo_url|e }}" alt="{{ logo_alt|e }}"/>
          </a></p>
        {%- endif %}
        {%- block headertitle %}
        <div class="headertitle"><a
          href="{{ pathto(root_doc)|e }}">{{ shorttitle|e }}</a></div>
        {%- endblock %}
        <div class="rel" role="navigation" aria-label="Related">
          {%- for rellink in rellinks|reverse %}
          <a href="{{ pathto(rellink[0])|e }}" title="{{ rellink[1]|striptags|e }}"
             {{ accesskey(rellink[2]) }}>{{ rellink[3] }}</a>
          {%- if not loop.last %}{{ reldelim2 }}{% endif %}
          {%- endfor %}
        </div>
       </div>
    </div>
{% endblock %}

{%- macro agogo_sidebar() %}
          {%- block sidebartoc %}
          <h3>{{ _('Table of Contents') }}</h3>
          {{ toctree(includehidden=True) }}
          {%- endblock %}
          {%- block sidebarsearch %}
          <search role="search">
            <h3 style="margin-top: 1.5em;">{{ _('Search') }}</h3>
            <form class="search" action="{{ pathto('search') }}" method="get">
                <input type="text" name="q" />
                <input type="submit" value="{{ _('Go') }}" />
            </form>
          </search>
          {%- endblock %}
{% endmacro %}

{% block content %}
    <div class="content-wrapper">
      <div class="content">
        {%- if not theme_rightsidebar|tobool %}
        <div class="sidebar">
          {{ agogo_sidebar() }}
        </div>
        {%- endif %}
        <div class="document">
          {%- block document %}
            {{ super() }}
          {%- endblock %}
        </div>
        {%- if theme_rightsidebar|tobool %}
        <div class="sidebar">
          {{ agogo_sidebar() }}
        </div>
        {%- endif %}
        <div class="clearer"></div>
      </div>
    </div>
{% endblock %}

{% block footer %}
    <div class="footer-wrapper">
      <div class="footer">
        <div class="left">
          <div role="navigation" aria-label="Related">
            {%- for rellink in rellinks|reverse %}
            <a href="{{ pathto(rellink[0])|e }}" title="{{ rellink[1]|striptags|e }}"
              {{ accesskey(rellink[2]) }}>{{ rellink[3] }}</a>
            {%- if not loop.last %}{{ reldelim2 }}{% endif %}
            {%- endfor %}
          </div>
          <div role="note" aria-label="source link">
            {%- if show_source and has_source and sourcename %}
              <br/>
              <a href="{{ pathto('_sources/' + sourcename, true)|e }}"
                rel="nofollow">{{ _('Show Source') }}</a>
            {%- endif %}
          </div>
        </div>

        <div class="right">
          {{ super() }}
        </div>
        <div class="clearer"></div>
      </div>
    </div>
{% endblock %}

{% block relbar1 %}{% endblock %}
{% block relbar2 %}{% endblock %}

/*
 * Sphinx stylesheet -- agogo theme.
 */

* {
  margin: 0px;
  padding: 0px;
}

body {
  font-family: {{ theme_bodyfont }};
  line-height: 1.4em;
  color: black;
  background-color: {{ theme_bgcolor }};

  /* fix for background colors breaking at horizontal
    scrolling on smaller devices */
  min-width: fit-content;
}


/* Page layout */

div.header, div.content, div.footer {
  width: {{ theme_pagewidth }};
  margin-left: auto;
  margin-right: auto;
}

div.header-wrapper {
  background: {{ theme_headerbg }};
  border-bottom: 3px solid #2e3436;
}


/* Default body styles */
a {
  color: {{ theme_linkcolor }};
}

a:visited {
  color: #551a8b;
}

div.bodywrapper a, div.footer a {
  text-decoration: underline;
}

.clearer {
  clear: both;
}

.left {
  float: left;
}

.right {
  float: right;
}

.line-block {
    display: block;
    margin-top: 1em;
    margin-bottom: 1em;
}

.line-block .line-block {
    margin-top: 0;
    margin-bottom: 0;
    margin-left: 1.5em;
}

h1, h2, h3, h4 {
  font-family: {{ theme_headerfont }};
  font-weight: normal;
  color: {{ theme_headercolor2 }};
  margin-bottom: .8em;
}

h1 {
  color: {{ theme_headercolor1 }};
}

h2 {
  padding-bottom: .5em;
  border-bottom: 1px solid {{ theme_headercolor2 }};
}

a.headerlink {
  visibility: hidden;
  color: #dddddd;
  padding-left: .3em;
}

h1:hover > a.headerlink,
h2:hover > a.headerlink,
h3:hover > a.headerlink,
h4:hover > a.headerlink,
h5:hover > a.headerlink,
h6:hover > a.headerlink,
